  'Adet başlangıç tarihlerini kişisel günlüğüne kaydet. Bu kayıtlar cihazın korumalı yerel depolamasında saklanır; otomatik bulut yedeklemesi yapılmaz. Döngü tahmini, doğurganlık hesabı ya da tıbbi değerlendirme yapılmaz.': 'Salve as datas de início da menstruação no seu diário pessoal. Esses registros ficam no armazenamento local protegido do aparelho; não há backup automático na nuvem. Não são feitas previsões de ciclo, cálculos de fertilidade nem avaliações médicas.',
