  'Adet gecikmesi, hafif kramp veya az miktarda lekelenme olabilir. Ev gebelik testi pozitif çıkabilir.': 'Atraso menstrual, cólicas leves ou um pequeno sangramento podem ocorrer. O teste de gravidez pode dar positivo.',
