  'Balık köftesi': 'Bolinhos de peixe',
  'Balık parçalarını tuz ve karabiberle tatlandırıp sebzelerin arasına yerleştirin, kalan sosu üzerine gezdirin.': 'Tempere o peixe com sal e pimenta, coloque entre os legumes e regue com o restante do molho.',
