  'Başını daha dik tutar; ellerini birleştirip ağzına götürür. Kahkahaya yakın sesler, renkli nesnelere uzun bakma.': 'Mantém a cabeça mais erguida; junta as mãos e leva à boca. Quase ri, olha por mais tempo objetos coloridos.',
  'Başını dik ve sabit tutar; nesnelere uzanır ve tutar. Kahkaha atar, yüzüstüyken kollarıyla doğrulur. Yuvarlanma denemeleri başlayabilir.': 'Mantém a cabeça erguida e firme; alcança e segura objetos. Ri, apoia-se nos braços de bruços. As tentativas de rolar podem começar.',
  'Başını kısa süre kaldırmayı dener; ellerini yumruk yapar. Sese irkilir veya sakinleşir. Gözüyle yakındaki yüzü kısa süre takip eder.': 'Tenta levantar a cabeça por um instante; as mãos ficam fechadas. Assusta-se ou se acalma com sons. Segue brevemente com os olhos um rosto próximo.',
