  'Bebek bakımı sırasında uyku bölünmesi kaçınılmazdır; ama uzun süreli uykusuzluk ruh sağlığını etkiler.': 'Sono interrompido é inevitável com um bebê, mas a falta de sono prolongada afeta a saúde mental.',
