  'Bebek hareketlerinde belirgin azalma veya durma: hemen başvur.': 'Diminuição clara ou ausência dos movimentos do bebê: procure atendimento imediatamente.',
  'Bebek hareketlerinde belirgin azalma, kanama, su gelmesi, düzenli kasılmalar, şiddetli baş ağrısı veya görme bozukluğu: aynı gün başvur. Acil durumda 112.': 'Diminuição clara dos movimentos do bebê, sangramento, perda de líquido, contrações regulares, dor de cabeça forte ou problemas de visão: procure atendimento no mesmo dia. Em uma emergência, ligue para o número de emergência local.',
