  'Bebek her uykuda sırtüstü yatırılmalıdır; yan veya yüzüstü yatış önerilmez.': 'Coloque o bebê de barriga para cima em todos os sonos; de lado ou de bruços não é recomendado.',
  'Bebek hızla büyüdüğü için kıyafet ve ekipmanlar kısa süre kullanılır.': 'Os bebês crescem rápido, então roupas e equipamentos são usados por pouco tempo.',
  'Bebek hızla kilo alır; doğuma hazırlık ve bebek hareketlerinin takibi önem kazanır.': 'O bebê ganha peso rápido; preparar-se para o parto e acompanhar os movimentos se torna importante.',
