  'Beslenme saatlerini ve miktarları takip ederek kendi kayıtlarınızı karşılaştırabilirsiniz. Yaşa uygun beslenme için sağlık uzmanınıza danışın.': 'Acompanhando os horários e as quantidades, você pode comparar seus próprios registros. Pergunte ao seu profissional de saúde qual alimentação é adequada à idade.',
  'Beslenme sonrası az miktarda süt çıkarmak ilk aylarda çok yaygındır ve genellikle zararsızdır.': 'Devolver pequenas quantidades de leite após as mamadas é muito comum nos primeiros meses e geralmente inofensivo.',
