  'Bez': 'Fralda',
  'Bez altına saklanan oyuncağı bulma, emeklemeyi teşvik eden tünel/yastık parkuru (gözetimli), "yok-oldu" oyunu.': 'Achar um brinquedo escondido sob um pano, circuito de túnel/almofadas para incentivar a engatinhar (com supervisão), brincadeira de "cadê?".',
  'Bez değişimi': 'Troca de fralda',
  'Bez değişimi sonrası ellerini iyice yıka.': 'Lave bem as mãos após trocar a fralda.',
  'Bez değiştirme ve beslenme malzemelerini evde 1–2 noktada topla.': 'Reúna os itens de troca e alimentação em 1–2 pontos da casa.',
  'Bez çantası': 'Bolsa de maternidade',
  'Bez ıslatmama, ağız kuruluğu, gözyaşı olmadan ağlama (susuzluk).': 'Sem fraldas molhadas, boca seca, choro sem lágrimas (desidratação).',
  'Bez, cilt ve beslenme kayıtlarını izleyin. Kontrolleri sağlık ekibinizle planlayın; ateş veya beslenme güçlüğünde yaşa uygun acil değerlendirme gereksinimini sorun.': 'Acompanhe os registros de fralda, pele e alimentação. Planeje as consultas com a equipe de saúde; pergunte sobre os critérios de urgência por idade em caso de febre ou dificuldade para se alimentar.',
  'Bezi sık değiştir (yenidoğanda günde 8–12 kez).': 'Troque a fralda com frequência (8–12 vezes por dia em recém-nascidos).',
  'Beşik çarşafı': 'Lençol de berço',
