  'Biberon ve emzikler her kullanımdan sonra yıkanmalıdır.': 'Mamadeiras e bicos devem ser lavados após cada uso.',
  'Biberon ve mama ile takviye, emzirme sıklığını azaltarak süt üretimini düşürebilir.': 'Complementar com mamadeira e fórmula pode reduzir a produção ao diminuir as mamadas.',
  'Biberonla beslenen bebekler daha fazla hava yutabilir.': 'Bebês que tomam mamadeira podem engolir mais ar.',
  'Biberonla beslerken emziği tamamen sütle dolu tutacak açı ver.': 'Na mamadeira, incline-a para que o bico fique sempre cheio de leite.',
  'Biberonla uykuya dalma ve şekerli içecekler diş sağlığını olumsuz etkileyebilir.': 'Dormir com mamadeira e bebidas açucaradas podem prejudicar a saúde dos dentes.',
