  'Daha önce dışa aktarılan yedekler ve panoya kopyalanan içerikler ayrıca silinmelidir. Kayıtları silmek açık rızanı geri almak anlamına gelir; uygulama bir sonraki açılışta yeniden onay ister.': 'Os backups exportados antes e o conteúdo copiado para a área de transferência precisam ser excluídos separadamente. Excluir os registros significa retirar seu consentimento explícito; o app pedirá o consentimento de novo na próxima abertura.',
