  'Doğranmış soğanı yağda yumuşatıp salçayı kavurun.': 'Refogue a cebola picada no azeite e frite o extrato.',
  'Doğru kavramada bebeğin ağzı geniş açık, dudakları dışa dönük ve meme başının çevresindeki koyu alanın büyük kısmı ağzındadır.': 'Com uma boa pega, a boca do bebê fica bem aberta, os lábios virados para fora e a maior parte da aréola dentro da boca.',
  'Doğru takılmış ve yaşa uygun oto koltuğu trafik kazalarında ölüm ve ağır yaralanma riskini büyük ölçüde azaltır.': 'Uma cadeirinha adequada à idade e bem instalada reduz muito o risco de morte e lesões graves em acidentes.',
  'Doğru temizlik, ayırma, pişirme ve soğutma gıda kaynaklı hastalıkları önler.': 'Limpar, separar, cozinhar e refrigerar corretamente previne doenças transmitidas por alimentos.',
