  'Doğum ağrısıyla baş etmek için ilaçsız ve ilaçlı birçok yöntem vardır.': 'Há muitas formas, com e sem medicamentos, de lidar com a dor do parto.',
  'Doğum başlamazsa doktorunun izlem planını öğren; genellikle 41. haftada değerlendirme yapılır.': 'Se o trabalho de parto não começar, saiba qual é o plano de acompanhamento do seu médico; geralmente há uma avaliação com 41 semanas.',
