  'Doğum planı ve hazırlık': 'Plano de parto e preparação',
  'Doğum planı, doğumla ilgili tercihlerini ekiple paylaşmanı kolaylaştıran kısa bir nottur.': 'O plano de parto é uma nota curta que ajuda a compartilhar suas preferências com a equipe.',
  'Doğum referansı eksik': 'Falta a referência de nascimento',
