  'Doğum sonrası destek': 'Apoio no pós-parto',
  'Doğum sonrası dikişler genellikle birkaç haftada iyileşir; temizlik ve dinlenme iyileşmeyi destekler.': 'Os pontos após o parto geralmente cicatrizam em poucas semanas; higiene e descanso ajudam.',
  'Doğum sonrası doğum kontrolü': 'Contracepção após o parto',
  'Doğum sonrası duygusal dalgalanmalar görülebilir. Yoğun üzüntü, kaygı veya işlev kaybı sürüyorsa profesyonel destek alın. Kendinize veya bebeğe zarar verme düşüncesinde acil yardım isteyin.': 'Altos e baixos emocionais são comuns depois do parto. Procure apoio profissional se a tristeza intensa, a ansiedade ou a dificuldade de funcionar continuarem. Peça ajuda de emergência se tiver pensamentos de machucar a si mesma ou ao bebê.',
  'Doğum sonrası günlük': 'Diário do pós-parto',
  'Doğum sonrası hüzün ve depresyon': 'Baby blues e depressão pós-parto',
  'Doğum sonrası idrar kaçırma yaygındır ve çoğu zaman tedavi edilebilir.': 'A perda de urina após o parto é comum e muitas vezes tem tratamento.',
  'Doğum sonrası ilk saat: ten tene temas': 'A primeira hora após o parto: contato pele a pele',
  'Doğum sonrası kontrol genellikle 6. haftada yapılır; daha erken kontroller de önerilebilir.': 'A consulta de pós-parto geralmente é com 6 semanas; consultas antes disso também podem ser recomendadas.',
  'Doğum sonrası kontrol randevumu planladım': 'Planejei minha consulta pós-parto',
  'Doğum sonrası kontrolde yöntem seçeneklerini hekiminle konuş.': 'Converse sobre as opções com o médico na consulta de pós-parto.',
  'Doğum sonrası kontrolleri sağlık ekibinizle planlayın. Kanama, ağrı, ilaçlar, korunma ve emzirme ile ilgili sorularınızı not edin.': 'Planeje as consultas pós-parto com sua equipe de saúde. Anote suas dúvidas sobre sangramento, dor, remédios, contracepção e amamentação.',
