  'Dudak/dil şişmesi, nefes darlığı, hırıltı, yaygın kurdeşen, bilinç değişikliği: 112.': 'Inchaço nos lábios/língua, falta de ar, chiado, urticária espalhada, alteração da consciência: ligue para o número de emergência local.',
