  'Duyguları adlandırma ("kızgın mısın?"), rol oyunları, açık havada tırmanma (alçak ve güvenli).': 'Nomear sentimentos ("você está bravo?"), faz de conta, escalar ao ar livre (baixo e seguro).',
  'Duyguları adlandırmasına yardım et ("kızgın görünüyorsun").': 'Ajude a nomear os sentimentos ("você parece bravo").',
  'Duygularını güvendiğin biriyle paylaş; yardım istemek güçlü bir adımdır.': 'Compartilhe seus sentimentos com alguém de confiança; pedir ajuda é um passo de coragem.',
  'Duygularını paylaşabileceğin kişilerle konuş.': 'Converse com pessoas com quem possa compartilhar seus sentimentos.',
  'Duyu': 'Sentidos',
  'Duyular gelişir; dokunmayı hissedebilir, kaşları belirir.': 'Os sentidos se desenvolvem; o bebê sente o toque e as sobrancelhas aparecem.',
  'Duyusal algı gelişir; hızla kilo alır.': 'A percepção sensorial se desenvolve; o bebê ganha peso rápido.',
  'Döküntü, dudak/dil şişmesi, kusma veya nefes darlığı: alerji, acil olabilir.': 'Manchas na pele, inchaço de lábios/língua, vômitos ou falta de ar: alergia, pode ser emergência.',
