  'Döngü, gebelik, doğum sonrası ve belirtiler': 'Ciclo, gravidez, pós-parto e sintomas',
  'Döngü, gebelik, doğum sonrası ve kontrol notları': 'Ciclo, gravidez, pós-parto e anotações de consultas',
  'Döngü, gebelik, doğum sonrası ve menopoz notları': 'Ciclo, gravidez, pós-parto e anotações da menopausa',
  'Döngünün sürekli 21 günden kısa veya 35 günden uzun olması.': 'Ciclos sempre menores que 21 dias ou maiores que 35.',
  'Dönüşten 2–3 hafta önce bakım düzenini denemeye başla.': 'Comece a testar o cuidado 2–3 semanas antes de voltar.',
