  'Gebeliğin yarısındasın. Bebek yutma hareketleri yapar; hareketleri belirginleşir.': 'Você chegou à metade. O bebê faz movimentos de engolir; os movimentos ficam mais claros.',
  'Gece Lambası': 'Luz noturna',
  'Gece beslemelerini eşinle veya bir yakınınla paylaşmayı planla.': 'Planeje dividir as mamadas noturnas com o parceiro ou alguém próximo.',
  'Gece beslenmelerini paylaştırmak için sağılmış süt veya mama seçeneğini değerlendir.': 'Considere leite retirado ou fórmula para poder dividir as mamadas noturnas.',
  'Gece kuruluğu gündüzden aylar hatta yıllar sonra gelebilir.': 'O desfralde noturno pode vir meses ou até anos depois do diurno.',
  'Gece lambası': 'Luz noturna',
  'Gece ve gündüz görevlerini birlikte paylaştırın; yazılı bir plan işe yarayabilir.': 'Dividam juntos as tarefas do dia e da noite; um plano por escrito pode ajudar.',
  'Gece yarısını geçen uyku, ilgili günlere paylaştırılır. Ölçek 24 saattir.': 'O sono que passa da meia-noite é dividido entre os dias correspondentes. A escala é de 24 horas.',
