  'Gereç gerekmez': 'Não precisa de material',
  'Gerginlik, uyku değişimi ve dikkat güçlüğünü gözlemleyin. Dinlenme, sosyal destek ve görev paylaşımı planlayın.': 'Observe tensão, mudanças no sono e dificuldade de concentração. Planeje descanso, apoio social e divisão de tarefas.',
