  'Göz muayenesi': 'Exame de vista',
  'Göz teması kurmama, adına tepki vermeme, işaret etmeme.': 'Não faz contato visual, não responde ao nome, não aponta.',
  'Göz teması kurmama, adına tepki vermeme.': 'Não faz contato visual, não responde ao nome.',
  'Göz ve işitme taramalarını aksatma.': 'Não perca os exames de visão e audição.',
  'Göz çapağını kaynatılıp soğutulmuş suya batırılmış temiz pamukla içten dışa sil.': 'Limpe os olhos grudados de dentro para fora com algodão limpo umedecido em água fervida e fria.',
  'Göz, göz bebeği': 'Olho, menina dos olhos',
  'Gözde kızarıklık ve yoğun sarı-yeşil çapak; yenidoğanda her zaman değerlendirilmeli.': 'Olho vermelho com secreção grossa amarelo-esverdeada; no recém-nascido sempre deve ser avaliado.',
  'Göze veya cilde temas ettiyse bol suyla en az 15 dakika yıka.': 'Se atingiu olhos ou pele, lave com bastante água por pelo menos 15 minutos.',
  'Gözetimli yüzüstü oyun': 'Tempo de bruços com supervisão',
  'Gözler açılmaya başlar; seslere tepki verebilir.': 'Os olhos começam a se abrir; o bebê pode reagir a sons.',
  'Gözler açılıp kapanabilir. Üçüncü trimester başlar.': 'Os olhos podem abrir e fechar. Começa o terceiro trimestre.',
  'Göğe ait, mavi': 'Celeste, azul',
