  'Kaliteli uyku ruh sağlığının temelidir; bebekli dönemde uykuyu korumak için plan yapmak gerekir.': 'Dormir bem é a base da saúde mental; com um bebê, é preciso um plano para protegê-lo.',
  'Kalkınca, yemeklerden sonra ve uyku öncesi lazımlığa oturmayı öner.': 'Sugira sentar no penico ao acordar, após as refeições e antes de dormir.',
