  'Kan şekeri düşük. Hızlı emilen şeker al, 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'Glicose baixa. Consuma açúcar de ação rápida e meça de novo após 15 minutos; se não melhorar, procure seu médico.',
  'Kan şekeri düşük: Hızlı emilen şeker al (ör. yarım bardak meyve suyu), 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'Glicose baixa: consuma açúcar de ação rápida (ex.: meio copo de suco de fruta) e meça de novo após 15 minutos; se não melhorar, procure seu médico.',
  'Kan şekeri yüksek. Doktorunun önerdiği hedeflere göre değerlendir.': 'Glicose alta. Avalie conforme as metas recomendadas pelo seu médico.',
