  'Kan şekeri çok yüksek. Doktoruna hemen başvur.': 'Glicose muito alta. Procure seu médico imediatamente.',
  'Kan şekeri ölçümlerini kaydet; doğumdan sonra kontrol testini yaptır.': 'Registre suas glicemias; faça o exame de controle após o parto.',
  'Kan; nimet': 'Sangue; bênção',
  'Kanama başlangıcı/bitişi, ağrı ve günlük etkileri not edin. Takvim doğum kontrol yöntemi değildir.': 'Anote início/fim do sangramento, dor e efeitos no dia. O calendário não é um método contraceptivo.',
