  'Kanama, pıhtı atma.': 'Sangramento, saída de coágulos.',
  'Kanama, su gelmesi, düzenli ağrılı kasılmalar, şiddetli baş ağrısı, görme bozukluğu, yüz ve ellerde ani şişlik: gecikmeden başvur.': 'Sangramento, perda de líquido, contrações regulares e doloridas, dor de cabeça forte, problemas de visão, inchaço repentino no rosto e nas mãos: procure atendimento sem demora.',
  'Kanama, şiddetli veya tek taraflı karın ağrısı, hiçbir şey tutamayacak kadar kusma, ateş: gecikmeden başvur.': 'Sangramento, dor forte ou de um lado só na barriga, vômitos a ponto de não segurar nada, febre: procure atendimento sem demora.',
