  'Küçük çocuklar sık düşer; çoğu düşme hafiftir ama bazı belirtiler acil değerlendirme gerektirir.': 'Crianças pequenas caem com frequência; a maioria das quedas é leve, mas alguns sinais exigem avaliação urgente.',
  'Küçük çocuklarda yaralanmaların çoğu evde olur ve büyük kısmı önlenebilir.': 'A maioria das lesões em crianças pequenas acontece em casa, e a maioria pode ser evitada.',
  'Küçük çocukların iştahı günden güne değişir; seçici yeme bu yaşlarda yaygındır.': 'O apetite das crianças pequenas varia de um dia para o outro; ser seletivo é comum nessa idade.',
  'Kılçıkları pişirmeden önce cımbızla almak servis sırasında kolaylık sağlar.': 'Retirar as espinhas com pinça antes de cozinhar facilita na hora de servir.',
  'Kılıf': 'Capa',
  'Kırmızı et, baklagil, yeşil yapraklı sebze gibi demir kaynaklarını tüket.': 'Coma fontes de ferro como carne vermelha, leguminosas e verduras verde-escuras.',
  'Kırmızı mercimek köftesi': 'Bolinhos de lentilha vermelha',
  'Kısa da olsa ikinize ayırdığınız zamanlar planlayın.': 'Reservem um tempo só para os dois, mesmo que curto.',
  'Kısa dinlenme araları planlayın; bakım sorumluluklarını paylaşın. Yorgunken bebeğinizle koltukta veya kanepede uyumamaya dikkat edin.': 'Planeje pausas curtas de descanso e divida os cuidados. Quando estiver cansada, cuidado para não adormecer com o bebê numa poltrona ou sofá.',
  'Kısa hikâye kurma ve neden-sonuç soruları ekleyin.': 'Acrescente criação de histórias curtas e perguntas de causa e efeito.',
  'Kısa nefes egzersizleri ve fiziksel aktivite stres tepkisini azaltır.': 'Exercícios curtos de respiração e atividade física diminuem a resposta ao estresse.',
  'Kısa nefes molası': 'Pausa rápida para respirar',
  'Kısa süre desteksiz oturabilir; sesin geldiği yöne döner. Hece tekrarları artar, ayna görüntüsüne ilgi gösterir.': 'Consegue sentar por pouco tempo sem apoio; vira-se na direção do som. O balbucio aumenta; mostra interesse pelo próprio reflexo.',
  'Kısa tekrarlar yapın; bebeğin bakışını ve tepkisini takip edin. Nesneleri ağzına götürmesine izin vermeyin.': 'Faça repetições curtas; acompanhe o olhar e as reações do bebê. Não deixe que leve objetos à boca.',
  'Kısa uyku. Bebeğin uyurken dinlenmeye, yardım istemeye çalış.': 'Sono curto. Tente descansar enquanto o bebê dorme e peça ajuda.',
  'Kısa ve kararlı vedalaş; gizlice ayrılma.': 'Despeça-se de forma breve e confiante; não saia escondido.',
  'Kısa şekerlemeler bile toparlanmaya yardımcı olur.': 'Mesmo cochilos curtos ajudam na recuperação.',
  'Kısa şekerlemeler bile yorgunluğu azaltır.': 'Mesmo cochilos curtos diminuem o cansaço.',
  'Kıskançlık sevginin değil, ilgiyi kaybetme korkusunun işaretidir.': 'O ciúme não é falta de amor, mas medo de perder atenção.',
  'Kısmi': 'Parcial',
  'Kısık ateşte 25-30 dakika pişirip limonla servis edin.': 'Cozinhe em fogo baixo por 25-30 minutos e sirva com limão.',
  'Kısık ateşte fasulyeler yumuşayana kadar 35-40 dakika pişirin.': 'Cozinhe em fogo baixo por 35-40 minutos até a vagem amolecer.',
  'Kısık ateşte iki tarafını tamamen pişirin.': 'Cozinhe bem dos dois lados em fogo baixo.',
  'Kısık ateşte karıştırarak 7-8 dakika koyulaştırın.': 'Deixe engrossar em fogo baixo por 7-8 minutos, mexendo.',
  'Kısık ateşte sebzeler yumuşayana kadar 25 dakika pişirin; ılıtarak servis edin.': 'Cozinhe em fogo baixo 25 minutos até os legumes amolecerem; sirva morno.',
  'Kısık ateşte suyunu çekene kadar pişirin; 10 dakika dinlendirin.': 'Cozinhe em fogo baixo até absorver a água; descanse 10 minutos.',
  'Kısık ateşte taneler yumuşayıp suyu çekene kadar 15-20 dakika pişirin.': 'Cozinhe em fogo baixo por 15-20 minutos até os grãos amolecerem e absorverem a água.',
  'Kıvamı püreden başlayıp yaşla birlikte parçalı ve parmak yiyeceklere ilerlet.': 'Comece com papinhas e avance, conforme a idade, para texturas com pedaços e alimentos para pegar com as mãos.',
  'Kıvrım içlerine yayılan, parlak kırmızı ve kenarında noktacıklar olan pişik mantar kaynaklı olabilir.': 'Uma vermelhidão intensa que se espalha pelas dobras com pontinhos nas bordas pode ser fungo.',
  'Kıyafet bakım etiketleri': 'Etiquetas de cuidado das roupas',
  'Kıyafetleri kullanım sıklığına göre gruplandırın. Kullanmadıklarınızı bağışlama veya onarma seçeneklerini değerlendirin.': 'Agrupe as roupas pela frequência de uso. Considere doar ou consertar as que não usa.',
  'Kıyma, rendelenmiş soğan, yumurta ve galeta ununu yoğurup köfte yapın.': 'Amasse a carne, a cebola ralada, o ovo e a farinha de rosca e modele as köfte.',
  'Kıyma, soğan, yumurta, galeta unu ve kimyonu yoğurun.': 'Amasse a carne moída, a cebola, o ovo, a farinha de rosca e o cominho.',
  'Kıymalı kabak': 'Abobrinha com carne moída',
  'Kıymalı patates': 'Batatas com carne moída',
