  'Kızarıklığın çevre cilde yayılması, şişlik, kötü kokulu akıntı.': 'Vermelhidão que se espalha pela pele ao redor, inchaço, secreção com mau cheiro.',
  'Kızıl şafak, tan': 'Aurora vermelha, alvorada',
