  'Lavaşları ısıtıp yoğurt ve tavuklu karışımla doldurarak sarın.': 'Aqueça o lavash, recheie com iogurte e o frango e enrole.',
  'Lazımlığı önceden tanıt; çocuğun oturmasına izin ver.': 'Apresente o penico com antecedência; deixe a criança sentar nele.',
  'Levrekleri iç ve dış yüzeyleriyle yıkayıp kâğıt havluyla kurulayın; derisine her iki yüzden 3\'er çapraz çizik atın.': 'Lave os robalos por dentro e por fora e seque; faça 3 cortes diagonais na pele de cada lado.',
