  'Limon suyu, ezilmiş sarımsak, zeytinyağı ve kekiği karıştırın.': 'Misture o suco de limão, o alho amassado, o azeite e o tomilho.',
  'Limon suyunu ekleyip tavanın dibini sıyırarak 1 dakika kaynatın, maydanozu ilave edin.': 'Junte o suco de limão e ferva 1 minuto raspando o fundo; acrescente a salsa.',
