  'Sebze ve meyveleri iyice yıka; eti tam pişir.': 'Lave bem frutas e verduras; cozinhe bem as carnes.',
  'Sebze yemekleri': 'Pratos de vegetais',
  'Sebze, meyve, protein ve tahıllarda çeşitlilik sağlayın. Çocuğu yemek hazırlığına yaşına uygun görevlerle katın; zorla yedirmekten kaçının.': 'Ofereça variedade de verduras, frutas, proteínas e grãos. Envolva a criança no preparo com tarefas adequadas à idade; evite forçar a comer.',
  'Sebze, meyve, tam tahıl, baklagil ve yeterli protein içeren dengeli öğünler hazırla.': 'Prepare refeições equilibradas com verduras, frutas, grãos integrais, leguminosas e proteína suficiente.',
  'Sebze, meyve, tam tahıl, protein ve süt ürünlerinden çeşitlilik sun. Ne yiyeceğine sen, ne kadar yiyeceğine çocuk karar versin. Şekerli içecekleri ve paketli atıştırmalıkları sınırla.': 'Ofereça variedade de verduras, frutas, grãos integrais, proteínas e laticínios. Você decide o que é servido; a criança decide quanto come. Limite bebidas açucaradas e salgadinhos industrializados.',
  'Sebzeler ve et tamamen yumuşayana kadar 20–25 dakika daha pişirin.': 'Cozinhe mais 20–25 minutos até os legumes e a carne ficarem bem macios.',
  'Sebzeler ve et tamamen yumuşayana kadar yaklaşık 25 dakika daha pişirin.': 'Cozinhe mais cerca de 25 minutos até os legumes e a carne ficarem bem macios.',
  'Sebzeler yumuşayıncaya kadar yaklaşık 20 dakika pişirin.': 'Cozinhe cerca de 20 minutos até os legumes amolecerem.',
  'Sebzeleri eşit boyutta doğrayın ki aynı anda pişsin.': 'Corte os legumes do mesmo tamanho para cozinharem juntos.',
  'Sebzeleri ince doğrayın ki balıkla aynı sürede pişsin.': 'Corte os legumes finos para cozinharem no mesmo tempo que o peixe.',
  'Sebzeleri iyice yıkayın.': 'Lave bem os legumes.',
  'Sebzeleri soyup eşit kalınlıkta dilimleyin.': 'Descasque os legumes e corte em fatias de espessura igual.',
  'Sebzeleri soyup uygun uzunlukta kesin.': 'Descasque os legumes e corte em palitos de tamanho adequado.',
  'Sebzeleri yağda 8-10 dakika yumuşayana kadar soteleyin.': 'Salteie os legumes no azeite por 8-10 minutos até amolecerem.',
  'Sebzeleri yumuşayana kadar pişirin.': 'Cozinhe os legumes até ficarem macios.',
  'Sebzeleri yıkayın.': 'Lave os legumes.',
  'Sebzeleri, mısırı ve ton balığını kasede birleştirin.': 'Junte os legumes, o milho e o atum numa tigela.',
  'Sebzelerin yarısını her kâğıdın ortasına yayın; alabalıkları tuz ve karabiberle ovup sebzelerin üzerine koyun.': 'Espalhe metade dos legumes no centro de cada papel; esfregue as trutas com sal e pimenta e coloque por cima.',
