  'Sesiniz': 'Sua voz',
  'Sesler uygulama içinde matematiksel olarak üretilir. Brahms Ninnisi (1868) ve “Parla Parla Küçük Yıldız” ezgisi kamu malıdır; “Uyku melodisi” bu uygulama için bestelenmiştir.': 'Os sons são gerados matematicamente no app. A Canção de ninar de Brahms (1868) e a melodia de "Brilha, brilha, estrelinha" são de domínio público; a "Melodia do sono" foi composta para este app.',
