  'Sezaryen büyük bir karın ameliyatıdır; iyileşme genellikle 6–8 hafta sürer.': 'A cesárea é uma grande cirurgia abdominal; a recuperação geralmente leva 6–8 semanas.',
  'Sezaryen sonrası ağır kaldırmaktan kaçın; öksürürken karnını yastıkla destekle.': 'Após a cesárea evite pegar peso; apoie a barriga com um travesseiro ao tossir.',
  'Sezaryen sonrası emzirme mümkündür; yan yatarak veya koltuk altı pozisyonu rahat olabilir.': 'Amamentar após a cesárea é possível; deitada de lado ou na posição de bola de futebol americano pode ser confortável.',
  'Sezaryen sonrası iyileşme': 'Recuperação após a cesárea',
  'Sezaryen sonrası tam iyileşme 6–8 hafta sürebilir.': 'A recuperação completa após uma cesárea pode levar 6–8 semanas.',
  'Sezaryen tıbbi gerekliliklerde hayat kurtarıcıdır; büyük bir ameliyat olduğu için iyileşmesi daha uzundur.': 'A cesárea salva vidas quando é medicamente necessária; por ser uma cirurgia grande, a recuperação é mais longa.',
  'Sezaryenden sonra da çoğu zaman mümkündür.': 'Muitas vezes é possível também após a cesárea.',
  'Seçenek sun ("kırmızı mı mavi mi?") ve küçük görevler ver.': 'Ofereça escolhas ("vermelho ou azul?") e dê pequenas tarefas.',
  'Seçenek sunma ("elma mı muz mu?"), kutu içine şekil yerleştirme, birlikte toplama oyunu.': 'Oferecer escolhas ("maçã ou banana?"), caixas de encaixar formas, arrumar juntos como brincadeira.',
