  'Siyah-beyaz kontrastlı kartlar, yüzünü yavaşça sağa-sola hareket ettirerek takip ettirme, günde birkaç kez karın üstü oyun.': 'Cartões de contraste preto e branco, mover devagar o rosto de um lado para o outro para ele acompanhar, brincar de bruços algumas vezes ao dia.',
