  'Somon küplerini ekleyip 3–4 dakika, tüm yüzleri açık renge dönene kadar nazikçe çevirin.': 'Junte os cubos de salmão e vire com cuidado por 3–4 minutos até clarearem por todos os lados.',
  'Somonları fırının orta rafında 15–18 dakika, eti çatalla kolayca ayrılana ve iç sıcaklığı 63 °C olana kadar pişirin.': 'Asse na grade do meio por 15–18 minutos, até a carne se soltar facilmente com o garfo e atingir 63 °C por dentro.',
  'Somonları soğuk suyla durulayıp kâğıt havluyla iyice kurulayın; derili tarafı alta gelecek şekilde tepsiye dizin.': 'Enxágue o salmão em água fria, seque com papel-toalha e coloque com a pele para baixo.',
