  'Son bir saattir kasılmalar 5 dakikada bir geliyor ve en az 1 dakika sürüyor. Doktorunu ya da doğum yapacağın hastaneyi ara; sana söylenen plana göre yola çık.': 'Na última hora, as contrações vieram a cada 5 minutos e duraram pelo menos 1 minuto. Ligue para seu médico ou para a maternidade onde vai dar à luz e saia conforme o plano combinado.',
