  'Trafik, oyun alanı, su güvenliği ve yabancılarla sınırlar konusunda yaşa uygun konuşun. Bisiklet ve benzeri etkinliklerde uygun koruyucu ekipman kullanın.': 'Converse de forma adequada à idade sobre trânsito, parquinhos, segurança na água e limites com estranhos. Use equipamentos de proteção para bicicleta e atividades parecidas.',
