  'Uzanabileceği mesafede güvenli oyuncak, farklı dokular, sesli kitaplar. Konuşurken duraklayıp "cevap" vermesini bekle.': 'Brinquedos seguros ao alcance, texturas diferentes, livros com sons. Ao conversar, faça pausas e espere a "resposta".',
