  'Vücut ısısı düşük görünüyor. Bebeği ısıt, ölçümü tekrarla; düşük kalıyorsa ya da bebek halsizse hemen doktora başvur.': 'A temperatura parece baixa. Aqueça o bebê e meça de novo; se continuar baixa ou o bebê estiver molinho, procure um médico imediatamente.',
