  'WHO persentili için doğrulanmış CDC/WHO 0–24 ay CSV dosyaları gereklidir. Üstteki yükleme simgesiyle resmi CSV içeriğini panodan içe aktarabilirsiniz. Referans yüklenmeden persentil hesaplanmaz.': 'Para os percentis da OMS, são necessários arquivos CSV CDC/OMS de 0–24 meses verificados. Você pode importar o conteúdo CSV oficial da área de transferência com o ícone de upload acima. Sem referência, os percentis não são calculados.',
