  'Yalnızca izleme, dinleme ve nazik karşılıklı etkileşim kullanın; bebeği zorlamayın. Hareket ve nesne gerektiren adımları uygulamayın.': 'Use apenas olhar, ouvir e uma troca suave; não force o bebê. Pule as etapas que exigem movimento ou objetos.',
