  'Yerde güvenli bir alanda, oturma ve uzanma becerisine göre yetişkin yardımıyla oynayın.': 'Brinquem no chão num lugar seguro, com ajuda de um adulto conforme a capacidade de sentar e deitar.',
  'Yerde güvenli bir hareket rotası hazırlayın.': 'Monte no chão um percurso seguro para se movimentar.',
  'Yerde güvenli bir minderde serbest hareket, oyuncağı biraz uzağa koyup uzanmasını teşvik etme, şarkılı el oyunları.': 'Movimento livre em um tapete seguro, deixar um brinquedo um pouco longe para incentivar a alcançar, músicas com brincadeiras de mão.',
