  'Yetişkin gözetiminde, yaşa uygun güvenli malzemelerle uygulayın. Çocuk istemezse ara verin.': 'Faça com supervisão de um adulto e materiais seguros e adequados à idade. Faça uma pausa se a criança não quiser.',
  'Yetişkin kadınlar için günlük toplam sıvı ihtiyacı yaklaşık 2–2,5 litredir; sıcak havada, gebelikte ve emzirmede artar.': 'Mulheres adultas precisam de cerca de 2–2,5 litros de líquidos por dia no total; mais no calor, na gravidez e na amamentação.',
  'Yetişkin kontrollü su': 'Água sob controle de um adulto',
  'Yetişkin sürekli gözetiminde uygulayın. Küçük parçalar, kopabilen nesneler, ipler ve boğulma riski oluşturan malzemeler kullanmayın. Bebek istemezse durun.': 'Faça sempre com supervisão constante de um adulto. Não use peças pequenas, objetos que se soltam, cordões ou materiais com risco de engasgo. Pare se o bebê não quiser.',
