  'Yumurtalar tamamen piştiğinde sıcak servis edin.': 'Sirva quente quando os ovos estiverem totalmente cozidos.',
  'Yumurtaları kırıp karıştırın.': 'Quebre os ovos e mexa.',
  'Yumurtayla karıştırın.': 'Misture com o ovo.',
  'Yumurtayı ekleyin.': 'Acrescente o ovo.',
  'Yumurtlama döneminde berrak, kaygan akıntı ve hafif kasık ağrısı olabilir.': 'Perto da ovulação pode haver corrimento transparente e elástico e uma leve dor pélvica.',
  'Yumurtlama ve verimli dönem, ortalama döngü süresine göre yaklaşık hesaplanır. Doğum kontrolü veya gebelik planlaması için güvenilir bir yöntem değildir; tıbbi değerlendirme yerine geçmez.': 'A ovulação e o período fértil são estimados a partir da duração média do seu ciclo. Não é um método confiável de contracepção ou planejamento de gravidez e não substitui a avaliação médica.',
  'Yumurtlama çoğunlukla bir sonraki adetten yaklaşık 14 gün önce olur.': 'A ovulação costuma ocorrer cerca de 14 dias antes da próxima menstruação.',
  'Yumurtlama çoğunlukla bu haftanın sonuna doğru olur; döllenme yumurtlamadan sonraki yaklaşık bir gün içinde gerçekleşebilir.': 'A ovulação costuma acontecer no fim desta semana; a fecundação pode ocorrer em cerca de um dia após a ovulação.',
  'Yumuşak Kitap': 'Livro de pano',
  'Yumuşak armut': 'Pera macia',
  'Yumuşak banyo havlusu.': 'Toalha de banho macia.',
  'Yumuşak bloklar, kapaklı kutular, el sallama ve alkış oyunu. Günlük işleri anlatarak konuşmayı sürdür.': 'Blocos macios, caixas com tampa, brincadeiras de dar tchau e bater palminhas. Continue narrando as tarefas do dia.',
  'Yumuşak engel yolu': 'Circuito macio de obstáculos',
