  'Yuvarlak ve köşeli şekilleri birlikte inceleyin.': 'Observem juntos formas redondas e com cantos.',
  'Yuvarlanma başladığı için alt değiştirme masasında elini bebekten ayırma. Küçük nesneleri, düğme pilleri ve ipleri ulaşamayacağı yerde tut.': 'Agora que ele rola, mantenha uma mão sobre ele no trocador. Deixe objetos pequenos, baterias de botão e fios fora de alcance.',
  'Yuvarlanır (çoğunlukla yüzüstüden sırtüstüne); nesneleri ağzına götürür. Adına tepki vermeye başlar, ses tonlarını ayırt eder.': 'Rola (geralmente de bruços para barriga para cima); leva objetos à boca. Começa a responder ao nome, distingue tons de voz.',
  'Yönetim verilerine erişilemedi. Yönetici yetkinizi, oturumunuzu ve sunucu kurulumunu kontrol edin.': 'Não foi possível acessar os dados de gestão. Verifique a permissão de administrador, a sessão e a configuração do servidor.',
  'Yönetim özeti • Ön izleme': 'Resumo de gestão • Prévia',
  'Yüce adların nuru': 'Luz dos nomes sublimes',
  'Yüce han': 'Cã elevado',
  'Yüce, yüksek': 'Elevado, sublime',
  'Yüce; Osmanlı padişahı': 'Elevado; sultão otomano',
  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'As referências carregadas ficam só enquanto esta tela estiver aberta. Os percentis mensais da OMS de 0–24 meses são informativos; não são uma avaliação médica.',
  'Yüksek ateş, aşırı halsizlik veya uyandırmakta güçlük.': 'Febre alta, fraqueza extrema ou difícil de acordar.',
  'Yüksek ateş, nefes darlığı, bayılma, nöbet: 112.': 'Febre alta, falta de ar, desmaio, convulsão: ligue para o número de emergência local.',
  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'Níveis muito altos de icterícia podem ser prejudiciais sem tratamento, por isso as consultas são importantes.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'Não deixe sozinho em superfícies altas. Mantenha peças pequenas, fios, remédios e bebidas quentes fora de alcance; use a cadeirinha adequada.',
  'Yüksek, yüce': 'Alto, elevado',
  'Yüksekten düşme, bilinç değişikliği veya kusma.': 'Queda de altura, alteração da consciência ou vômitos.',
  'Yükseliş': 'Ascensão',
  'Yükseliş; merdiven': 'Ascensão; escada',
  'Yükselme, terakki': 'Ascensão, progresso',
  'Yükselmek': 'Elevar-se',
  'Yürüme için güvenli alan, basit şekil yerleştirme, birlikte şarkı ve kitap. 1 yaş kontrolüne git.': 'Um espaço seguro para andar, encaixes simples de formas, músicas e livros juntos. Vá à consulta de 1 ano.',
  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'Andar, as primeiras palavras e a vontade de independência marcam esta fase.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'Não use andador: ele aumenta o risco de quedas e lesões.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'Caminhada, natação, bicicleta ergométrica e yoga para gestantes são opções seguras.',
  'Yürüyüşle başlayıp yavaş yavaş artır.': 'Comece caminhando e aumente aos poucos.',
  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'Expressões faciais podem começar; o corpo começa a ser coberto por uma penugem fina (lanugem).',
  'Yüz ifadelerini keşfet': 'Explorar expressões faciais',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'Divida limpeza, hidratação e proteção solar em três passos curtos. Acrescente produtos novos um de cada vez e observe a reação da pele.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'Inchaço repentino no rosto e nas mãos, falta de ar: procure ajuda imediatamente.',
  'Yüz-dil şişmesi, solunum güçlüğü veya baygınlık gibi bulgular acil değerlendirme gerektirir.': 'Sinais como inchaço no rosto ou na língua, dificuldade para respirar ou desmaio exigem avaliação de emergência.',
  'Yüzey temizleyici': 'Limpador multiuso',
