  'Yıkama ve ütü talimatlarını kontrol edin. Hassas kumaşları uygun programda yıkayın; kurutma talimatlarına uyun.': 'Confira as instruções de lavagem e passadoria. Lave tecidos delicados no programa adequado; siga as instruções de secagem.',
