  'İhtişam, gösteriş': 'Esplendor, magnificência',
  'İki adımlı küçük görevler ekleyin; başarıyı değil keşfi öne çıkarın.': 'Acrescente pequenas tarefas de dois passos; valorize a descoberta, não o acerto.',
  'İki aşamalı basit yönergeleri, hayalî oyunu ve sosyal etkileşimi birlikte deneyimleyin.': 'Experimentem juntos instruções simples de dois passos, faz de conta e interação social.',
  'İki blok üst üste koyma, büyük boya kalemiyle karalama (gözetimli), saklambaç benzeri basit oyunlar.': 'Empilhar dois blocos, rabiscar com giz de cera grosso (com supervisão), brincadeiras simples de esconde-esconde.',
  'İki dilli büyüyen çocuklarda kelime dağarcığı iki dile dağılabilir; bu gecikme anlamına gelmez.': 'Crianças bilíngues podem dividir o vocabulário entre duas línguas; isso não é atraso.',
  'İki elle tutulacak oyuncaklar, birbirine vurma (ritim), aynada yüz ifadeleri.': 'Brinquedos para segurar com as duas mãos, bater objetos um no outro (ritmo), caretas no espelho.',
  'İki forumun SQL dosyaları, RLS politikaları ve çok kullanıcılı testleri gerekli.': 'São necessários arquivos SQL, políticas RLS e testes multiusuário para os dois fóruns.',
  'İki forumun canlı Supabase bağlantısı ve RLS politikaları doğrulandı': 'A conexão Supabase ao vivo e as políticas RLS dos dois fóruns foram verificadas',
  'İki haftadan uzun süren mutsuzluk, ilgi kaybı, umutsuzluk.': 'Tristeza, perda de interesse ou desesperança por mais de duas semanas.',
  'İki haftadan uzun süren mutsuzluk, umutsuzluk, uykusuzluk.': 'Tristeza, desesperança ou insônia por mais de duas semanas.',
  'İki sözcüklü cümleler yaygınlaşır; 50 civarı sözcük olağandır. Taklit ve hayali oyun artar.': 'Frases de duas palavras ficam comuns; cerca de 50 palavras é normal. Imitação e faz de conta aumentam.',
  'İki tarafını da içi tamamen pişene kadar çevirerek pişirin.': 'Vire e cozinhe dos dois lados até cozinhar bem por dentro.',
  'İki yaş: koşar, top atar, 2–3 sözcüklü cümleler kurar, basit iki aşamalı yönergeleri yapar. Tuvalet eğitimine hazırlık belirtileri görülebilir.': 'Dois anos: corre, joga bola, forma frases de 2–3 palavras, segue instruções simples de dois passos. Sinais de prontidão para o desfralde podem aparecer.',
  'İki yüzünü de yumurta tamamen pişene kadar pişirin.': 'Cozinhe dos dois lados até o ovo ficar bem cozido.',
