  'İlaç, temizlik ürünü veya bitki yutulması çocuklarda sık görülen acil durumlardandır.': 'Engolir remédios, produtos de limpeza ou plantas é uma emergência comum em crianças.',
  'İlaçları ve temizlik ürünlerini kilitli, yüksek dolaplarda orijinal kutusunda sakla.': 'Guarde remédios e produtos de limpeza na embalagem original, trancados e no alto.',
  'İlaçları yalnızca yaşa, kiloya ve hekim önerisine uygun şekilde kullanın.': 'Use remédios somente de acordo com a idade, o peso e a orientação médica.',
  'İlaçları çocukların erişemeyeceği güvenli bir yerde saklayın.': 'Guarde os remédios em local seguro, fora do alcance das crianças.',
  'İlaçları, temizlik ürünlerini ve küçük nesneleri erişimden uzak tutun. Yaşa uygun oto koltuğu kullanın.': 'Mantenha remédios, produtos de limpeza e objetos pequenos fora do alcance. Use cadeirinha adequada à idade.',
  'İlerlemeyi mükemmellik üzerinden değerlendirmeyin.': 'Não meça seu progresso pela perfeição.',
