  'İletişimde kalmak istediğiniz kişileri belirleyin. Düzenli kısa görüşmeler için uygun zamanlar planlayın.': 'Identifique as pessoas com quem quer manter contato. Planeje horários para conversas curtas e regulares.',
  'İlgilendiğiniz bir konu seçin. Her gün kısa okuma veya uygulama zamanı ayırın. Öğrendiklerinizi kendi cümlelerinizle not edin.': 'Escolha um tema que te interesse. Reserve um tempo curto por dia para ler ou praticar. Anote o que aprendeu com suas palavras.',
